import { useModalContext } from "#components/contexts/ModalContext.js";
import { useOrderContext } from "#components/contexts/OrderContext.js";
import { useUsersContext } from "#components/contexts/UserContext.js";
import { Button } from "reactstrap";
import AddToolProductModal from "../modal/addProductModal/AddToolProductModal";
import "../ordersView.css";

const ToolJournalTableOrder = ({
  productListOrder,
  onProductClickHandler,
  filterKeys = [],
  deleteHandler,
  displayNames = {},
}) => {
  const { setNewOrder, orderCartData } = useOrderContext();
  const { toolProductModalOrder, setToolProductModalOrder } = useModalContext();
  const { userAccess } = useUsersContext();

  const columns = Object.keys(productListOrder?.[0] || {}).filter(
    (key) => !filterKeys.includes(key) && key !== "warehouse_id" && key
  );

  return (
    <>
      {toolProductModalOrder && (
        <AddToolProductModal
          isOpen={toolProductModalOrder}
          toggle={() => setToolProductModalOrder(!toolProductModalOrder)}
        />
      )}{" "}
      <div className="ord-prod-card">
        <div className="ord-prod-card__head">
          <span className="ord-badge" style={{ background: "#efe9fb", color: "#7c3aed" }}>
            Herramienta
          </span>
          <div className="ord-prod-card__title">Tools</div>
        </div>
        <table className="product-table ord-prod-table">
          <thead>
            <tr>
              {columns.map((key) => (
                <th key={key}>{displayNames[key] || key}</th>
              ))}
              <th>Actions</th>
            </tr>
          </thead>

          <tbody>
            {Array.isArray(productListOrder) &&
              productListOrder.map((product) => (
                <tr
                  key={product?.id || Math.random()}
                  onClick={() => onProductClickHandler(product)}
                  style={{ cursor: "pointer" }}
                >
                  {columns.map((key) => {
                    let value = product[key];
                    if (value && typeof value === "object") {
                      value = JSON.stringify(value);
                    }
                    return <td key={key}>{value ?? ""}</td>;
                  })}

                  <td onClick={(e) => e.stopPropagation()}>
                    {orderCartData?.status < 3 && (
                      <Button
                        size="sm"
                        color="danger"
                        className="ord-mini-btn ord-mini-btn--danger ord-btn"
                        onClick={() => deleteHandler(product)}
                      >
                        Delete
                      </Button>
                    )}
                  </td>
                </tr>
              ))}

            {userAccess?.canWrite && orderCartData?.status < 3 && (
              <tr>
                <td colSpan={columns.length + 1}>
                  <Button
                    block
                    className="ord-add-row"
                    onClick={() => {
                      setNewOrder((prev) => ({
                        ...prev,
                        article: orderCartData.article,
                        owner: orderCartData.owner?.id,
                        status: orderCartData.status,
                        del_adr_id: orderCartData.deliveryAddress?.id,
                      }));
                      setToolProductModalOrder(!toolProductModalOrder);
                    }}
                  >
                    + Add product
                  </Button>
                </td>
              </tr>
            )}
          </tbody>
        </table>
      </div>
    </>
  );
};

export default ToolJournalTableOrder;
